/* SA.brain.montage — 22-electrode BCI IV-2a montage positions for the brain-graph view.
 * Coordinates come ONLY from SA.data.montage (generated by research/export/montage.py from
 * MNE colin27_1005, projected; unit head circle, +y = nose). Never hand-typed here.
 * If the data file is missing, a computed schematic grid (rows 1/5/7/5/3/1, ADR 0005 D24)
 * is used and source() says so. FCz = index 3, Cz = index 9 (0-based; paper Fig. 2a: 4 and 10).
 * DOM-free; safe to load in Node. */
(function (root) {
  'use strict';
  var SA = root.SA = root.SA || {};
  SA.brain = SA.brain || {};

  // Channel ORDER of the BCI IV-2a montage (names only; matches sfegatWeights.manifest.channels).
  var NAMES = ['Fz', 'FC3', 'FC1', 'FCz', 'FC2', 'FC4', 'C5', 'C3', 'C1', 'Cz', 'C2', 'C4', 'C6',
    'CP3', 'CP1', 'CPz', 'CP2', 'CP4', 'P1', 'Pz', 'P2', 'POz'];
  var ROWS = [1, 5, 7, 5, 3, 1];
  var MAX_R = 0.86;           // electrodes are scaled to sit inside this radius of the unit head

  var cache = null;

  function fromData(d) {
    if (!d || !d.channels || d.channels.length !== NAMES.length) return null;
    var out = [];
    for (var i = 0; i < d.channels.length; i++) {
      var c = d.channels[i];
      if (!c || typeof c.x !== 'number' || typeof c.y !== 'number' || !isFinite(c.x) || !isFinite(c.y)) return null;
      out.push({ name: String(c.name), idx: i, paperIdx: c.paperIdx || (i + 1), x: c.x, y: c.y });
    }
    // Fit inside MAX_R without distorting the projection (uniform scale only).
    var r = 0;
    out.forEach(function (p) { r = Math.max(r, Math.sqrt(p.x * p.x + p.y * p.y)); });
    var k = r > MAX_R ? MAX_R / r : 1;
    out.forEach(function (p) { p.x *= k; p.y *= k; });
    return out;
  }

  function schematic() {
    // Computed grid: rows evenly spaced front (+y) to back (-y), columns evenly spaced.
    var out = [], i = 0, nRows = ROWS.length;
    for (var r = 0; r < nRows; r++) {
      var y = 0.72 - r * (1.44 / (nRows - 1));
      var n = ROWS[r], span = n === 1 ? 0 : Math.min(1.5, 0.26 * (n - 1));
      for (var c = 0; c < n; c++) {
        var x = n === 1 ? 0 : -span / 2 + c * (span / (n - 1));
        out.push({ name: NAMES[i], idx: i, paperIdx: i + 1, x: x, y: y });
        i++;
      }
    }
    return out;
  }

  function build() {
    var data = SA.data && SA.data.montage;
    var pts = fromData(data);
    if (pts) {
      var src = (data.manifest && data.manifest.source) || 'SA.data.montage';
      return { pts: pts, source: src, schematic: false };
    }
    return { pts: schematic(), source: 'schematic grid (montage data missing)', schematic: true };
  }

  function get() { if (!cache) cache = build(); return cache; }

  SA.brain.montage = {
    names: NAMES.slice(),
    FCZ: 3,
    CZ: 9,
    /** @returns {{name, idx, paperIdx, x, y}[]} 22 entries, unit head circle, +y = nose. */
    positions: function () {
      return get().pts.map(function (p) { return { name: p.name, idx: p.idx, paperIdx: p.paperIdx, x: p.x, y: p.y }; });
    },
    index: function (name) {
      var pts = get().pts;
      for (var i = 0; i < pts.length; i++) if (pts[i].name === name) return i;
      return -1;
    },
    source: function () { return get().source; },
    isSchematic: function () { return get().schematic; },
    invalidate: function () { cache = null; }
  };
})(typeof window !== 'undefined' ? window : globalThis);
